<?php
declare(strict_types=1);
require __DIR__ . '/app/bootstrap.php';
$page = (string)($_GET['page'] ?? 'home');
$u = user();
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    check_csrf();
    $action = (string)($_POST['action'] ?? '');
    try {
        if ($action === 'login') {
            $email = strtolower(request_text('email', 190)); $pass = (string)($_POST['password'] ?? '');
            $s = db()->prepare('SELECT id,password_hash FROM users WHERE email=?'); $s->execute([$email]); $row = $s->fetch();
            if (!$row || !$row['password_hash'] || !password_verify($pass, $row['password_hash'])) throw new RuntimeException('Correo o contraseña incorrectos.');
            login_user((int)$row['id']); redirect('index.php');
        }
        if ($action === 'signup') {
            if (!cfg('allow_local_signup')) throw new RuntimeException('El registro local está desactivado.');
            $name=request_text('name',120); $email=strtolower(request_text('email',190)); $pass=(string)($_POST['password'] ?? '');
            if (!$name || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($pass)<12) throw new RuntimeException('Completa nombre, correo y una contraseña de al menos 12 caracteres.');
            $s=db()->prepare("INSERT INTO users (name,email,password_hash,role) VALUES (?,?,?,'student')");
            $s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]); login_user((int)db()->lastInsertId()); redirect('index.php');
        }
        if ($action === 'new_ticket') {
            $u=require_user();
            $subject=request_text('subject',180); $supportType=request_text('support_type',2); $category=request_text('category',80); $description=request_text('description',10000);
            // La base instalada exige urgency; ya no es una respuesta del solicitante.
            $urgency='media';
            $types=support_types();
            $validCategory=isset($types[$supportType]) && in_array($category,$types[$supportType]['categories'],true);
            if (!$subject || mb_strlen($subject)<6 || !$validCategory || mb_strlen($description)<20) throw new RuntimeException('Selecciona un tipo de soporte y una categoría correspondiente; completa también el asunto y la descripción.');
            $course=request_text('course',180);
            $priority=priority_for_urgency($urgency);
            db()->beginTransaction();
            $s=db()->prepare('INSERT INTO tickets (user_id,subject,category,description,course,course_url,impact,urgency,priority,level) VALUES (?,?,?,?,?,?,?,?,?,?)');
            // La columna impact sigue siendo obligatoria en la base instalada; no representa una respuesta del usuario.
            $s->execute([$u['id'],$subject,$category,$description,$course,null,'individual',$urgency,$priority,$supportType]);
            $id=(int)db()->lastInsertId(); $code=ticket_code($id);
            $s=db()->prepare('UPDATE tickets SET code=? WHERE id=?'); $s->execute([$code,$id]);
            event($id,(int)$u['id'],'created','Solicitud creada por el solicitante. Clasificación inicial: '.support_type_name($supportType).' · '.$category.'.');
            db()->commit();
            try { save_upload($id,null,(int)$u['id']); } catch (RuntimeException $e) { flash('Solicitud creada sin adjunto: '.$e->getMessage(),'warning'); }
            if (empty($_SESSION['flash'])) flash('Solicitud '.$code.' radicada. Puedes seguirla desde Mis solicitudes.');
            redirect('index.php?page=ticket&id='.$id);
        }
        if ($action === 'message') {
            $u=require_user(); $ticket=ticket_by_id((int)($_POST['ticket_id'] ?? 0));
            if (!$ticket || !can_view_ticket($ticket,$u)) { http_response_code(404); exit('Solicitud no encontrada.'); }
            $body=request_text('body',10000); $internal=is_staff($u) && !empty($_POST['internal']) ? 1 : 0;
            if (mb_strlen($body)<2) throw new RuntimeException('Escribe un mensaje antes de enviarlo.');
            $s=db()->prepare('INSERT INTO messages (ticket_id,user_id,body,internal) VALUES (?,?,?,?)'); $s->execute([$ticket['id'],$u['id'],$body,$internal]);
            $messageId=(int)db()->lastInsertId();
            if (is_staff($u) && !$internal && !$ticket['first_response_at']) { $s=db()->prepare('UPDATE tickets SET first_response_at=NOW() WHERE id=?'); $s->execute([$ticket['id']]); }
            if (!is_staff($u) && in_array($ticket['status'],['waiting','resolved','closed'],true)) { $s=db()->prepare("UPDATE tickets SET status='progress',resolved_at=NULL WHERE id=?"); $s->execute([$ticket['id']]); event((int)$ticket['id'],(int)$u['id'],'status','El solicitante respondió; la solicitud volvió a atención.'); }
            event((int)$ticket['id'],(int)$u['id'],$internal?'internal_note':'message',$internal?'Nota interna añadida.':'Mensaje añadido.');
            try { save_upload((int)$ticket['id'],$messageId,(int)$u['id']); } catch (RuntimeException $e) { flash('Mensaje guardado sin adjunto: '.$e->getMessage(),'warning'); }
            if (empty($_SESSION['flash'])) flash('Mensaje enviado.');
            redirect('index.php?page=ticket&id='.$ticket['id'].'#conversation');
        }
        if ($action === 'update_ticket') {
            $u=require_staff(); $ticket=ticket_by_id((int)($_POST['ticket_id'] ?? 0));
            if (!$ticket) { http_response_code(404); exit('Solicitud no encontrada.'); }
            $status=request_text('status',20); $level=request_text('level',5); $assigned=(int)($_POST['assigned_to'] ?? 0);
            if (!in_array($status,['new','assigned','progress','waiting','resolved','closed'],true) || !in_array($level,['N1','N2','N3'],true)) throw new RuntimeException('Estado o nivel inválido.');
            if ($assigned) { $s=db()->prepare("SELECT id FROM users WHERE id=? AND role IN ('agent','admin')"); $s->execute([$assigned]); if (!$s->fetchColumn()) throw new RuntimeException('Selecciona un agente válido.'); }
            if ($status==='closed' && !in_array($ticket['status'],['resolved','closed'],true)) throw new RuntimeException('Resuelve la solicitud antes de cerrarla.');
            $s=db()->prepare('UPDATE tickets SET status=?,level=?,assigned_to=?,resolved_at=CASE WHEN ?=\'resolved\' AND resolved_at IS NULL THEN NOW() ELSE resolved_at END WHERE id=?');
            $s->execute([$status,$level,$assigned ?: null,$status,$ticket['id']]);
            if ($status!==$ticket['status'] || $level!==$ticket['level'] || $assigned!==(int)$ticket['assigned_to']) event((int)$ticket['id'],(int)$u['id'],'updated','Estado: '.status_label($status).' · Nivel: '.$level.' · Responsable: '.($assigned ?: 'sin asignar').'.');
            flash('Solicitud actualizada.'); redirect('index.php?page=ticket&id='.$ticket['id']);
        }
        if ($action === 'rating') {
            $u=require_user(); $ticket=ticket_by_id((int)($_POST['ticket_id'] ?? 0)); $rating=(int)($_POST['rating'] ?? 0);
            if (!$ticket || (int)$ticket['user_id']!==(int)$u['id'] || !in_array($ticket['status'],['resolved','closed'],true) || $rating<1 || $rating>5) throw new RuntimeException('Valoración inválida.');
            $s=db()->prepare('UPDATE tickets SET rating=? WHERE id=?'); $s->execute([$rating,$ticket['id']]);
            event((int)$ticket['id'],(int)$u['id'],'rating','El solicitante valoró la atención.');
            flash('Gracias por valorar la atención.'); redirect('index.php?page=ticket&id='.$ticket['id']);
        }
        if ($action === 'role') {
            $u=require_admin(); $id=(int)($_POST['user_id'] ?? 0); $role=request_text('role',20);
            if (!in_array($role,['student','agent','admin'],true) || $id===(int)$u['id']) throw new RuntimeException('Cambio de rol inválido.');
            $s=db()->prepare('UPDATE users SET role=? WHERE id=?'); $s->execute([$role,$id]);
            flash('Rol actualizado.'); redirect('index.php?page=team');
        }
        throw new RuntimeException('Acción desconocida.');
    } catch (PDOException $e) {
        error_log($e); $error=$e->getCode()==='23000'?'Ya existe una cuenta con ese correo.':'No se pudo guardar. Revisa el registro de errores del servidor.';
    } catch (RuntimeException $e) { $error=$e->getMessage(); }
}
if ($page==='logout') { $_SESSION=[]; session_regenerate_id(true); redirect('index.php?page=login'); }
$public=in_array($page,['login','signup'],true);
if (!$public) $u=require_user();
if ($page==='queue' || $page==='team') $u=$page==='team'?require_admin():require_staff();
function render_header(string $title, string $active): void {
    $u=user(); $flash=take_flash();
    ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#6279F6"><title><?=h($title)?> · Unidad Virtual</title><link rel="stylesheet" href="https://use.typekit.net/doy5gsv.css"><link rel="stylesheet" href="assets/style.css?v=20261016-tipografia"><script src="assets/app.js?v=20261015-formulario" defer></script></head><body><div class="app-shell"><aside class="sidebar"><a class="brand" href="<?=h(url('index.php'))?>" aria-label="Ir al inicio"><span class="brand-logo-frame"><img class="brand-logo" src="assets/imagotipo-uninunez-virtual.png" alt="Uninúñez Virtual" width="3140" height="1430"></span></a><div class="sidebar-label">ESPACIO DE SOPORTE</div><nav class="side-nav" aria-label="Principal"><a class="<?=$active==='home'?'active':''?>" href="<?=h(url('index.php'))?>"><span>⌂</span> Inicio</a><a class="<?=$active==='new'?'active':''?>" href="<?=h(url('index.php?page=new'))?>"><span>＋</span> Nueva solicitud</a><a class="<?=$active==='tickets'?'active':''?>" href="<?=h(url('index.php?page=tickets'))?>"><span>▤</span> Mis solicitudes</a><?php if(is_staff($u)): ?><div class="sidebar-label second">EQUIPO</div><a class="<?=$active==='queue'?'active':''?>" href="<?=h(url('index.php?page=queue'))?>"><span>◫</span> Bandeja de atención</a><?php endif; if($u['role']==='admin'): ?><a class="<?=$active==='team'?'active':''?>" href="<?=h(url('index.php?page=team'))?>"><span>♧</span> Equipo y roles</a><?php endif ?></nav><div class="sidebar-bottom"><div class="profile"><span class="avatar"><?=h(mb_strtoupper(mb_substr($u['name'],0,1)))?></span><span><strong><?=h($u['name'])?></strong><small><?=h($u['role']==='student'?'Solicitante':($u['role']==='admin'?'Administrador':'Agente'))?></small></span><a href="<?=h(url('index.php?page=logout'))?>" title="Cerrar sesión" aria-label="Cerrar sesión">⇥</a></div></div></aside><div class="main-area"><header class="topbar"><button class="menu-toggle" aria-label="Abrir menú" aria-expanded="false">☰</button><span class="breadcrumb">Unidad Virtual <span>›</span> <?=h($title)?></span></header><main class="content"><?php if($flash): ?><div class="alert <?=h($flash[1])?>"><?=h($flash[0])?></div><?php endif; ?><?php
}
function render_footer(): void { ?></main><footer class="footer">Unidad Virtual · Uninúñez</footer></div></div></body></html><?php }
function render_auth(string $title, string $subtitle, string $error): void {
    ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> · Unidad Virtual</title><link rel="stylesheet" href="https://use.typekit.net/doy5gsv.css"><link rel="stylesheet" href="assets/style.css?v=20261016-tipografia"></head><body class="auth-body"><main class="auth-layout"><section class="auth-intro"><a class="auth-brand" href="<?=h(url('index.php?page=login'))?>" aria-label="Ir al inicio de sesión"><span class="brand-logo-frame"><img class="brand-logo" src="assets/imagotipo-uninunez-virtual.png" alt="Uninúñez Virtual" width="3140" height="1430"></span></a><div><div class="eyebrow light">MESA DE AYUDA DIGITAL</div><h1>Estamos aquí para ayudarte a seguir avanzando.</h1><p>Un solo lugar para resolver dudas sobre tu aula virtual, actividades, acceso y experiencia de aprendizaje.</p><div class="auth-steps"><span>01 · Cuéntanos qué pasa</span><span>02 · Hacemos seguimiento</span><span>03 · Te ayudamos a resolverlo</span></div></div><small>Educación virtual que te acompaña.</small></section><section class="auth-panel"><div class="auth-box"><div class="eyebrow">BIENVENIDO A SOPORTE</div><h2><?=h($title)?></h2><p><?=h($subtitle)?></p><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; $f=take_flash(); if($f): ?><div class="alert <?=h($f[1])?>"><?=h($f[0])?></div><?php endif; ?><?php
}
function render_auth_end(): void { ?></div></section></main></body></html><?php }

if ($page==='login') {
    render_auth('Ingresa a tu cuenta','Consulta tus solicitudes y recibe acompañamiento.', $error);
    ?><form method="post" class="stack auth-form"><?=csrf_field()?><input type="hidden" name="action" value="login"><label>Correo electrónico<input name="email" type="email" placeholder="tu.correo@uninunez.edu.co" required autocomplete="email"></label><label>Contraseña<input name="password" type="password" placeholder="Tu contraseña" required autocomplete="current-password"></label><button class="button primary full">Ingresar <span>→</span></button></form><?php if(!empty(cfg('google')['client_id']) && !empty(cfg('google')['client_secret'])): ?><div class="divider">o continúa con</div><a class="button google full" href="<?=h(url('google.php'))?>"><span class="google-g">G</span> Cuenta de Google</a><?php endif; if(cfg('allow_local_signup')): ?><p class="auth-foot">¿Aún no tienes cuenta? <a href="<?=h(url('index.php?page=signup'))?>">Crear cuenta para la prueba</a></p><?php endif; render_auth_end(); exit;
}
if ($page==='signup') {
    if (!cfg('allow_local_signup')) redirect('index.php?page=login');
    render_auth('Crea tu cuenta','Regístrate para iniciar una solicitud de soporte.', $error);
    ?><form method="post" class="stack auth-form"><?=csrf_field()?><input type="hidden" name="action" value="signup"><label>Nombre completo<input name="name" required maxlength="120" autocomplete="name"></label><label>Correo electrónico<input name="email" type="email" required autocomplete="email"></label><label>Contraseña <small>12 caracteres como mínimo</small><input name="password" type="password" required minlength="12" autocomplete="new-password"></label><button class="button primary full">Crear cuenta <span>→</span></button></form><p class="auth-foot">¿Ya tienes cuenta? <a href="<?=h(url('index.php?page=login'))?>">Inicia sesión</a></p><?php render_auth_end(); exit;
}
if ($page==='home') {
    $s=db()->prepare('SELECT COUNT(*) total, SUM(status IN (\'new\',\'assigned\',\'progress\',\'waiting\')) open_count, SUM(status IN (\'resolved\',\'closed\')) done_count FROM tickets WHERE user_id=?'); $s->execute([$u['id']]); $stats=$s->fetch();
    $s=db()->prepare('SELECT id,code,subject,category,status,priority,created_at FROM tickets WHERE user_id=? ORDER BY created_at DESC LIMIT 4'); $s->execute([$u['id']]); $recent=$s->fetchAll();
    render_header('Inicio','home');
    ?><section class="welcome"><div class="welcome-content"><h1>Hola, <?=h(explode(' ',trim($u['name']))[0])?></h1><p>Tu espacio para resolver inquietudes y continuar aprendiendo. Cuéntanos qué necesitas y te acompañamos.</p><a class="button white" href="<?=h(url('index.php?page=new'))?>">Crear nueva solicitud <span>↗</span></a></div><div class="welcome-art" aria-hidden="true"><div class="art-orbit orbit-a"></div><div class="art-orbit orbit-b"></div><div class="art-card art-back"><span>✦</span> Aprendizaje</div><div class="art-card art-front"><div class="art-chat">···</div><strong>¿Necesitas ayuda?</strong><small>Estamos para ti</small><div class="art-line"></div><div class="art-line short"></div></div><div class="art-bubble">✓</div></div></section><div class="section-head"><div><div class="eyebrow">TU ESPACIO</div><h2>¿Cómo podemos ayudarte?</h2><p>Elige una opción para comenzar.</p></div></div><div class="category-grid"><a class="category-card" href="<?=h(url('index.php?page=new&support_type=N1&category='.rawurlencode('Ubicación de aulas, actividades o recursos')))?>"><span class="category-icon lilac">▣</span><strong>Aula virtual</strong><small>Acceso a cursos y asignaturas</small><span class="card-arrow">↗</span></a><a class="category-card" href="<?=h(url('index.php?page=new&support_type=N2&category='.rawurlencode('Fallas en actividades, recursos o notificaciones')))?>"><span class="category-icon blue">✎</span><strong>Actividades</strong><small>Tareas, evaluaciones y entregas</small><span class="card-arrow">↗</span></a><a class="category-card" href="<?=h(url('index.php?page=new&support_type=N1&category='.rawurlencode('Ingreso a la plataforma')))?>"><span class="category-icon peach">◉</span><strong>Acceso y cuenta</strong><small>Ingreso y recuperación</small><span class="card-arrow">↗</span></a><a class="category-card" href="<?=h(url('index.php?page=new'))?>"><span class="category-icon mint">⋯</span><strong>Otro tema</strong><small>Explora todas las opciones</small><span class="card-arrow">↗</span></a></div><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><div class="eyebrow">SEGUIMIENTO</div><h2>Tus solicitudes recientes</h2></div><a href="<?=h(url('index.php?page=tickets'))?>">Ver todas →</a></div><?php if(!$recent): ?><div class="empty"><span class="empty-icon">☷</span><strong>Aún no tienes solicitudes</strong><p>Cuando necesites ayuda, podrás seguir aquí el avance de tu caso.</p><a class="button outline" href="<?=h(url('index.php?page=new'))?>">Crear solicitud</a></div><?php else: ?><div class="ticket-list"><?php foreach($recent as $t): ?><a class="ticket-row" href="<?=h(url('index.php?page=ticket&id='.$t['id']))?>"><span class="ticket-row-icon">▤</span><span class="ticket-row-main"><strong><?=h($t['subject'])?></strong><small><?=h($t['code'])?> · <?=h($t['category'])?></small></span><span class="status <?=h($t['status'])?>"><?=h(status_label($t['status']))?></span><span class="row-chevron">›</span></a><?php endforeach ?></div><?php endif ?></section><aside class="panel stats-panel"><div class="eyebrow">RESUMEN</div><h2>Tu actividad</h2><div class="stat-row"><span class="stat-icon all">▤</span><div><strong><?=h((int)$stats['total'])?></strong><small>Solicitudes creadas</small></div></div><div class="stat-row"><span class="stat-icon open">◷</span><div><strong><?=h((int)$stats['open_count'])?></strong><small>En seguimiento</small></div></div><div class="stat-row"><span class="stat-icon done">✓</span><div><strong><?=h((int)$stats['done_count'])?></strong><small>Resueltas</small></div></div><div class="stats-note">Cada paso de tu solicitud queda registrado para que sepas cómo avanza.</div></aside></div><?php render_footer(); exit;
}
