}
if ($page==='ticket') {
    $ticket=ticket_by_id((int)($_GET['id'] ?? 0));
    if(!$ticket || !can_view_ticket($ticket,$u)){http_response_code(404);exit('Solicitud no encontrada.');}
    $s=db()->prepare('SELECT m.*,u.name FROM messages m JOIN users u ON u.id=m.user_id WHERE m.ticket_id=? AND (m.internal=0 OR ?=1) ORDER BY m.created_at,id'); $s->execute([$ticket['id'],is_staff($u)?1:0]); $messages=$s->fetchAll();
    $s=db()->prepare('SELECT * FROM attachments WHERE ticket_id=? ORDER BY id'); $s->execute([$ticket['id']]); $attachments=$s->fetchAll();
    $s=db()->prepare('SELECT e.*,u.name AS actor_name FROM ticket_events e LEFT JOIN users u ON u.id=e.actor_id WHERE e.ticket_id=? ORDER BY e.created_at DESC,e.id DESC'); $s->execute([$ticket['id']]); $events=$s->fetchAll();
    $agents=[]; if(is_staff($u)) $agents=db()->query("SELECT id,name FROM users WHERE role IN ('agent','admin') ORDER BY name")->fetchAll();
    $sla=sla_target($ticket);
    render_header('Detalle de solicitud',is_staff($u)?'queue':'tickets');
    if ($error) echo '<div class="alert error">' . h($error) . '</div>';
    ?><div class="ticket-top"><a class="subtle-link" href="<?=h(url('index.php?page='. (is_staff($u)?'queue':'tickets')))?>">← Volver a solicitudes</a><span class="code-pill"><?=h($ticket['code'])?></span></div><div class="ticket-title"><div><div class="eyebrow"><?=h($ticket['category'])?> · <?=h(support_type_name($ticket['level']))?></div><h1><?=h($ticket['subject'])?></h1><p>Creada el <?=h(date_label($ticket['created_at']))?> por <?=h($ticket['student_name'])?></p></div><span class="status big <?=h($ticket['status'])?>"><?=h(status_label($ticket['status']))?></span></div><div class="detail-layout"><div class="detail-main"><section class="panel detail-panel"><div class="panel-heading"><div><div class="eyebrow">TU CASO</div><h2>Descripción</h2></div><span class="priority-chip"><?=h($ticket['priority'])?></span></div><p class="description-text"><?=nl2br(h($ticket['description']))?></p><?php if($ticket['course']||$ticket['course_url']): ?><div class="detail-meta"><div><small>Curso o asignatura</small><strong><?=h($ticket['course'] ?: 'No indicado')?></strong></div><?php if($ticket['course_url']): ?><div><small>Enlace del aula</small><a href="<?=h($ticket['course_url'])?>" target="_blank" rel="noopener noreferrer">Abrir aula ↗</a></div><?php endif ?></div><?php endif; if($attachments): ?><div class="attachment-list"><strong>Evidencias</strong><?php foreach($attachments as $a): ?><a href="<?=h(url('download.php?id='.$a['id']))?>">↧ <?=h($a['original_name'])?> <small><?=h(round($a['file_size']/1024))?> KB</small></a><?php endforeach ?></div><?php endif ?></section><section id="conversation" class="panel detail-panel"><div class="panel-heading"><div><div class="eyebrow">ACOMPAÑAMIENTO</div><h2>Conversación</h2></div></div><?php if(!$messages): ?><div class="conversation-empty">Tu solicitud ya está registrada. Aquí verás los mensajes y actualizaciones del equipo.</div><?php endif; foreach($messages as $m): ?><div class="message <?=$m['internal']?'internal-message':((int)$m['user_id']===(int)$ticket['user_id']?'student-message':'agent-message')?>"><span class="message-avatar"><?=h(mb_strtoupper(mb_substr($m['name'],0,1)))?></span><div><div class="message-head"><strong><?=h($m['name'])?></strong><?php if($m['internal']): ?><span>Nota interna</span><?php endif ?><small><?=h(date_label($m['created_at']))?></small></div><p><?=nl2br(h($m['body']))?></p></div></div><?php endforeach ?><form method="post" enctype="multipart/form-data" class="reply-form"><?=csrf_field()?><input type="hidden" name="action" value="message"><input type="hidden" name="ticket_id" value="<?=h($ticket['id'])?>"><label for="reply">Añadir respuesta</label><textarea id="reply" name="body" rows="4" required placeholder="Escribe aquí tu mensaje..."></textarea><div class="reply-actions"><label class="attach-control">＋ Adjuntar evidencia <input name="evidence" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"></label><?php if(is_staff($u)): ?><label class="checkbox"><input type="checkbox" name="internal" value="1"> Nota interna, invisible para el solicitante</label><?php endif ?><button class="button primary">Enviar respuesta →</button></div></form></section><?php if(!is_staff($u) && in_array($ticket['status'],['resolved','closed'],true)): ?><section class="panel rating-panel"><h2>¿Cómo fue la atención?</h2><p>Tu opinión nos ayuda a mejorar.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="rating"><input type="hidden" name="ticket_id" value="<?=h($ticket['id'])?>"><div class="rating-buttons"><?php for($i=1;$i<=5;$i++): ?><button name="rating" value="<?=$i?>" class="rating-button <?=$ticket['rating']===$i?'selected':''?>" aria-label="Calificar <?=$i?> de 5">★ <span><?=$i?></span></button><?php endfor ?></div></form></section><?php endif ?></div><aside class="detail-side"><section class="panel side-panel"><div class="eyebrow">INFORMACIÓN</div><h2>Detalles del caso</h2><div class="side-line"><small>Estado</small><span class="status <?=h($ticket['status'])?>"><?=h(status_label($ticket['status']))?></span></div><div class="side-line"><small>Tipo de soporte actual</small><strong><?=h(support_type_name($ticket['level']))?></strong></div><div class="side-line"><small>Prioridad interna</small><strong><?=h($ticket['priority'])?></strong></div><div class="side-line"><small>Responsable</small><strong><?=h($ticket['agent_name'] ?: 'Por asignar')?></strong></div><div class="side-line"><small>Última actualización</small><strong><?=h(date_label($ticket['updated_at']))?></strong></div></section><?php if(is_staff($u)): ?><section class="panel side-panel"><div class="eyebrow">GESTIÓN DEL EQUIPO</div><h2>Actualizar caso</h2><form method="post" class="stack compact"><?=csrf_field()?><input type="hidden" name="action" value="update_ticket"><input type="hidden" name="ticket_id" value="<?=h($ticket['id'])?>"><label>Estado<select name="status"><?php foreach(['new','assigned','progress','waiting','resolved','closed'] as $v): ?><option value="<?=$v?>" <?=$ticket['status']===$v?'selected':''?>><?=h(status_label($v))?></option><?php endforeach ?></select></label><label>Nivel de atención<select name="level"><?php foreach(['N1','N2','N3'] as $v): ?><option value="<?=$v?>" <?=$ticket['level']===$v?'selected':''?>><?=h(support_type_name($v))?> (<?=$v?>)</option><?php endforeach ?></select></label><label>Responsable<select name="assigned_to"><option value="0">Sin asignar</option><?php foreach($agents as $a): ?><option value="<?=h($a['id'])?>" <?=(int)$ticket['assigned_to']===(int)$a['id']?'selected':''?>><?=h($a['name'])?></option><?php endforeach ?></select></label><button class="button primary full">Guardar cambios</button></form><p class="tiny-note">El tipo indica el nivel de atención actual. La conexión automática con TIC requiere acceso a su sistema.</p></section><?php endif ?><section class="panel side-panel"><div class="eyebrow">TRAZABILIDAD</div><h2>Actividad</h2><div class="timeline"><?php foreach($events as $e): ?><div><span class="timeline-dot"></span><strong><?=h($e['details'])?></strong><small><?=h(date_label($e['created_at']))?></small></div><?php endforeach ?></div></section></aside></div><?php render_footer(); exit;
}
if ($page==='queue') {
    $status=(string)($_GET['status']??'open'); $valid=['open','all','new','assigned','progress','waiting','resolved','closed']; if(!in_array($status,$valid,true)) $status='open';
    $query=trim(mb_substr((string)($_GET['q']??''),0,100));
    $sql='SELECT t.id,t.code,t.subject,t.category,t.status,t.priority,t.level,t.created_at,t.first_response_at,t.assigned_to,u.name student_name,a.name agent_name FROM tickets t JOIN users u ON u.id=t.user_id LEFT JOIN users a ON a.id=t.assigned_to WHERE 1=1'; $args=[];
    if($status==='open') $sql.=" AND t.status IN ('new','assigned','progress','waiting')"; elseif($status!=='all'){$sql.=' AND t.status=?';$args[]=$status;}
    if($query!==''){$sql.=' AND (t.code LIKE ? OR t.subject LIKE ? OR u.name LIKE ?)';$like='%'.$query.'%';array_push($args,$like,$like,$like);}
    $sql.=" ORDER BY FIELD(t.priority,'P1','P2','P3','P4'),t.created_at ASC LIMIT 250";
    $s=db()->prepare($sql);$s->execute($args);$tickets=$s->fetchAll();
    $overdueCount=0; foreach($tickets as $ticketRow) if(sla_target($ticketRow)['overdue']) $overdueCount++;
    $counts=db()->query("SELECT COUNT(*) total, SUM(status='new') new_count, SUM(status IN ('new','assigned','progress','waiting')) open_count, SUM(level='N3' AND status NOT IN ('resolved','closed')) escalated FROM tickets")->fetch();
    render_header('Bandeja de atención','queue');
    if ($overdueCount) echo '<div class="alert warning">' . h($overdueCount) . ' solicitudes de esta vista superaron la meta interna de atención. Revísalas por prioridad.</div>';
    ?><div class="page-heading"><div><div class="eyebrow">ESPACIO DEL EQUIPO</div><h1>Bandeja de atención</h1><p>Prioriza, asigna y acompaña cada solicitud.</p></div></div><div class="queue-stats"><div><span class="stat-icon all">▤</span><strong><?=h((int)$counts['total'])?></strong><small>Solicitudes totales</small></div><div><span class="stat-icon open">◷</span><strong><?=h((int)$counts['open_count'])?></strong><small>Activas</small></div><div><span class="stat-icon new">✦</span><strong><?=h((int)$counts['new_count'])?></strong><small>Sin revisar</small></div><div><span class="stat-icon escalated">↗</span><strong><?=h((int)$counts['escalated'])?></strong><small>Tipo 3</small></div></div><div class="queue-toolbar"><div class="filter-tabs compact-tabs"><?php foreach(['open'=>'Activas','new'=>'Nuevas','waiting'=>'Esperando','resolved'=>'Resueltas','all'=>'Todas'] as $key=>$label): ?><a class="<?=$status===$key?'active':''?>" href="<?=h(url('index.php?page=queue&status='.$key))?>"><?=h($label)?></a><?php endforeach ?></div><form method="get" class="search-form"><input type="hidden" name="page" value="queue"><input type="hidden" name="status" value="<?=h($status)?>"><input name="q" value="<?=h($query)?>" placeholder="Buscar ticket o solicitante" aria-label="Buscar ticket"><button aria-label="Buscar">⌕</button></form></div><section class="panel list-panel"><?php if(!$tickets): ?><div class="empty large"><span class="empty-icon">☷</span><strong>No hay tickets en esta vista</strong><p>Las nuevas solicitudes aparecerán aquí.</p></div><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Solicitud</th><th>Solicitante</th><th>Prioridad</th><th>Tipo</th><th>Responsable</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($tickets as $t): ?><tr><td><a class="table-link" href="<?=h(url('index.php?page=ticket&id='.$t['id']))?>"><?=h($t['subject'])?></a><small><?=h($t['code'])?> · <?=h(date_label($t['created_at']))?></small></td><td><?=h($t['student_name'])?></td><td><span class="priority-chip <?=h(strtolower($t['priority']))?>"><?=h($t['priority'])?></span></td><td><?=h(support_type_name($t['level']))?></td><td><?=h($t['agent_name']?:'Sin asignar')?></td><td><span class="status <?=h($t['status'])?>"><?=h(status_label($t['status']))?></span></td><td><a class="round-arrow" aria-label="Ver solicitud" href="<?=h(url('index.php?page=ticket&id='.$t['id']))?>">›</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><p class="tiny-note">Se muestran hasta 250 solicitudes. Las metas de atención son internas y configurables en <code>config.php</code>.</p><?php render_footer(); exit;
}
if ($page==='team') {
    $users=db()->query('SELECT id,name,email,role,created_at FROM users ORDER BY FIELD(role,\'admin\',\'agent\',\'student\'),name LIMIT 300')->fetchAll();
    render_header('Equipo y roles','team');
    ?><div class="page-heading"><div><div class="eyebrow">ADMINISTRACIÓN</div><h1>Equipo y roles</h1><p>Asigna quién puede atender y administrar solicitudes.</p></div></div><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif ?><section class="panel list-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Nombre</th><th>Correo</th><th>Rol actual</th><th>Cambiar rol</th></tr></thead><tbody><?php foreach($users as $member): ?><tr><td><strong><?=h($member['name'])?></strong></td><td><?=h($member['email'])?></td><td><?=h(['student'=>'Solicitante','agent'=>'Agente','admin'=>'Administrador'][$member['role']] ?? $member['role'])?></td><td><?php if((int)$member['id']===(int)$u['id']): ?>Tu cuenta<?php else: ?><form method="post" class="role-form"><?=csrf_field()?><input type="hidden" name="action" value="role"><input type="hidden" name="user_id" value="<?=h($member['id'])?>"><select name="role" aria-label="Rol de <?=h($member['name'])?>"><option value="student" <?=$member['role']==='student'?'selected':''?>>Solicitante</option><option value="agent" <?=$member['role']==='agent'?'selected':''?>>Agente</option><option value="admin" <?=$member['role']==='admin'?'selected':''?>>Administrador</option></select><button class="button outline small">Guardar</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></section><p class="tiny-note">Los usuarios aparecen aquí después de registrarse o iniciar sesión con Google. Se muestran los primeros 300.</p><?php render_footer(); exit;
}
if ($page==='help') redirect('index.php');
http_response_code(404); render_header('Página no encontrada',''); ?><div class="empty large"><strong>No encontramos esta página</strong><a class="button primary" href="<?=h(url('index.php'))?>">Ir al inicio</a></div><?php render_footer();
